using System.Linq; using System.Web.Mvc; using EmployeeManagement.Data; using EmployeeManagement.Models;
namespace EmployeeManagement.Controllers { public class EmployeesController : Controller { ApplicationDbContext db=new ApplicationDbContext(); public ActionResult Index(string search) { var q=db.Employees.Include("Department").AsQueryable(); if(!string.IsNullOrEmpty(search)) q=q.Where(x=>x.FullName.Contains(search)||x.Email.Contains(search)); ViewBag.Search=search; return View(q.OrderBy(x=>x.FullName).ToList()); } public ActionResult Create(){ViewBag.Departments=new SelectList(db.Departments,"Id","Name");return View("Form",new Employee{HireDate=System.DateTime.Today});} [HttpPost,ValidateAntiForgeryToken] public ActionResult Create(Employee item){if(!ModelState.IsValid){Load(item.DepartmentId);return View("Form",item);}db.Employees.Add(item);db.SaveChanges();return RedirectToAction("Index");} public ActionResult Edit(int id){var x=db.Employees.Find(id);if(x==null)return HttpNotFound();Load(x.DepartmentId);return View("Form",x);} [HttpPost,ValidateAntiForgeryToken] public ActionResult Edit(Employee item){if(!ModelState.IsValid){Load(item.DepartmentId);return View("Form",item);}db.Entry(item).State=System.Data.Entity.EntityState.Modified;db.SaveChanges();return RedirectToAction("Index");} [HttpPost,ValidateAntiForgeryToken] public ActionResult Delete(int id){var x=db.Employees.Find(id);if(x!=null){db.Employees.Remove(x);db.SaveChanges();}return RedirectToAction("Index");} void Load(int id){ViewBag.Departments=new SelectList(db.Departments,"Id","Name",id);} } }